<div class="page-head"><div><span class="eyebrow">COMMERCIAL</span><h1>Ventes</h1><p class="muted">Historique des transactions.</p></div><a class="btn primary" href="<?= e(url('/sales/create')) ?>">＋ Nouvelle vente</a></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Référence</th><th>Client</th><th>Date</th><th>Montant</th><th>Mode de paiement</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= e($r['invoice_no']) ?></b></td><td><?= e($r['customer']??'Comptoir') ?></td><td><?= e(date('d/m/Y H:i',strtotime($r['created_at']))) ?></td><td><?= money($r['total']) ?></td><td><?= e($r['payment_method']) ?></td><td><a href="<?= e(url('/invoice')) ?>?id=<?= (int)$r['id'] ?>">Facture →</a></td></tr><?php endforeach; ?></tbody></table></div></section>